update public.content_variants set body = $json${"type":"multiple_choice","answer":"If the sector goes down, all stocks are affected","options":["Cheaper administration costs","If the sector goes down, all stocks are affected","Taxes are always lower","Guaranteed bigger dividends"],"question":"What are the risks of buying multiple stocks from the same sector?","difficulty":"intermediate","parameters":{},"explanation":"Stocks in the same sector tend to move in the same direction, so sector diversification is important."}$json$::jsonb where id = 'a0bc6f99-aea4-4e50-97b5-283ad3d70bca';
